Rc::new(NameResult {
    name: "".to_string(),
    span: current_span(tokens.clone(), state.clone()),
    state: state.clone(),
    err: Some(parse_error(v2_rt::concat("expected name, found ".to_string(), found.clone()), current_span(tokens.clone(), state.clone()))),
})
