pub fn modifier_to_prop(name: String, span: Rc<SourceSpan>) -> Rc<Node> {
    make_field_init_node(name.clone(), make_expr_node(Rc::new(ExprData::ExprLiteral {
    value: Rc::new(LiteralValue::LitBool {
    value: true,
}),
}), Rc::new(vec![]), None, span.clone()), span.clone())
}

pub fn modifiers_to_props(modifiers: Rc<Vec<OperationModifier>>, span: Rc<SourceSpan>) -> Rc<Vec<Rc<Node>>> {
    Rc::new({ let mut __result = Vec::new(); for m in modifiers.clone().iter().cloned() { __result.push(match m.clone() {
    OperationModifier::Idempotent => modifier_to_prop("idempotent".to_string(), span.clone()),
    OperationModifier::Readonly => modifier_to_prop("readonly".to_string(), span.clone()),
    OperationModifier::Hermetic => modifier_to_prop("hermetic".to_string(), span.clone()),
}); } __result })
}

pub fn status_expr_to_str(expr: Rc<Node>) -> String {
    match (*expr.expr_data.clone()).clone() {
    ExprData::ExprLiteral { ref value, .. } => match value.as_ref() {
        LiteralValue::LitInt { value: n, .. } => int_to_string(n.clone()),
        LiteralValue::LitStr { value: s, .. } => s.clone(),
        _ => "_".to_string(),
    },
    ExprData::ExprVar { .. } => expr_var_name(expr.clone()),
    _ => "_".to_string(),
}
}

pub fn int_to_string(value: i64) -> String {
    if (value.clone() == 0) {
        "0".to_string()
} else {
        {
            let digits: Rc<Vec<String>> = int_to_string_acc(value.clone(), Rc::new(vec![]));
digits.clone().join(&"".to_string())
}
}
}

pub fn int_to_string_acc(mut value: i64, mut acc: Rc<Vec<String>>) -> Rc<Vec<String>> {
    loop {
        if (value.clone() == 0) {
            break acc.clone();
} else {
            let digit: i64 = (value.clone() % 10);
let rest: i64 = ((value.clone() - digit.clone()) / 10);
let digit_chars: Rc<Vec<String>> = Rc::new(vec!["0".to_string(), "1".to_string(), "2".to_string(), "3".to_string(), "4".to_string(), "5".to_string(), "6".to_string(), "7".to_string(), "8".to_string(), "9".to_string()]);
let ch: String = match Rc::new({ let mut __result = Vec::new(); for p in Rc::new(digit_chars.clone().iter().cloned().enumerate().map(|(i, v)| (i as i64, v)).collect::<Vec<_>>()).iter().cloned() { if (p.0.clone() == digit.clone()) { __result.push(p); } } __result }).first().cloned() {
    Some(p) => p.1.clone(),
    None => "?".to_string(),
};
{
                let __tco_0 = rest.clone();
let __tco_1 = v2_rt::rc_list_push(acc.clone(), ch.clone());
value = __tco_0;
acc = __tco_1;
continue;
}
}
}
}

pub fn first_child_or_self(n: Rc<Node>) -> Rc<Node> {
    match n.children.clone().first().cloned() {
    Some(ch) => ch.clone(),
    None => n.clone(),
}
}

pub fn last_child_or_self(n: Rc<Node>) -> Rc<Node> {
    match n.children.clone().last().cloned() {
    Some(ch) => ch.clone(),
    None => n.clone(),
}
}

pub fn node_to_name_str(n: Rc<Node>) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        {
            let has_children: bool = ((n.children.clone().len() as i64) > 0);
let is_optional: bool = (n.return_cardinality.clone() == Cardinality::CardOptional);
let is_keyed_container: bool = (is_container_type(n.name.clone()) && ((n.children.clone().len() as i64) == 2));
if is_optional.clone() {
                v2_rt::concat("Optional_".to_string(), node_to_name_str(with_required_cardinality(n.clone())))
} else {
                if is_keyed_container.clone() {
                    if ((n.children.clone().len() as i64) > 1) {
                        v2_rt::concat(v2_rt::concat(n.name.clone(), "_".to_string()), node_to_name_str(last_child_or_self(n.clone())))
} else {
                        n.name.clone()
}
} else {
                    if (n.name.clone().as_str() == "Refined".to_string().as_str()) {
                        if has_children.clone() {
                            node_to_name_str(first_child_or_self(n.clone()))
} else {
                            n.name.clone()
}
} else {
                        if is_container_type(n.name.clone()) {
                            if has_children.clone() {
                                v2_rt::concat("List_".to_string(), node_to_name_str(first_child_or_self(n.clone())))
} else {
                                n.name.clone()
}
} else {
                            if (n.name.clone().as_str() == "".to_string().as_str()) {
                                {
                                    let is_conj: bool = (n.connective.clone() == Connective::Conj);
let is_disj: bool = (n.connective.clone() == Connective::Disj);
if is_conj.clone() {
                                        "Record".to_string()
} else {
                                        if is_disj.clone() {
                                            "Union".to_string()
} else {
                                            n.name.clone()
}
}
}
} else {
                                n.name.clone()
}
}
}
}
}
}
    })
}

